    ).toEqual({
      approval: {
        id: "appr-1",
        approve: true,
        decision: { kind: "acceptOnce" },
        structured: false,
        invalidReason: null,
        binding: "ab_deadbeef",
      },
    });
    // a non-string binding is ignored (stays null)
    expect(
      parseInputEvent(
        '{"type":"approval","id":"appr-1","approve":true,"binding":5}',
      ),
    ).toEqual({
      approval: {
        id: "appr-1",
