  });

  it("validates structured decisions and fails closed on drift", () => {
    expect(
      parseInputEvent(
        '{"type":"approval","id":"appr-1","decision":{"kind":"acceptForTurn","permissions":[{"capability":"tool:run_shell","scope":"npm test"}]},"approve":true,"binding":"ab_bound"}',
      ),
